import{_ as t,o,c as a,ag as r}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 6 — From Spec to App","description":"","frontmatter":{"source":"weeks/06-spec-to-app/README.md"},"headers":[],"relativePath":"weeks/06-spec-to-app/index.md","filePath":"weeks/06-spec-to-app/index.md"}'),s={name:"weeks/06-spec-to-app/index.md"};function i(d,e,n,h,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="week-6--from-spec-to-app" tabindex="-1">Week 6 — From Spec to App <a class="header-anchor" href="#week-6--from-spec-to-app" aria-label="Permalink to &quot;Week 6 — From Spec to App&quot;">​</a></h1><blockquote><p>Judge an app by your criteria, keep the code you can read, and write the check before the code.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (≤30 min)</td><td>Read this page and skim the <a href="./bake-off-scorecard.html">bake-off scorecard</a>. Check that you can sign in to the app builder your instructor gave you (Google AI Studio, 18+, or Bolt). Have your <code>SPEC.md</code> open on GitHub</td></tr><tr><td><strong>Studio A</strong></td><td>The <strong>builder bake-off</strong> as a jigsaw: you score one app builder against your own spec, then compare with a partner who tested the other. The class results board</td></tr><tr><td><strong>Studio B</strong></td><td>Start Project 1 in a Codespace in Safe Loop order: rules in their own module, <strong>check first</strong> with an automated test, preview before you commit, Console when the page goes blank. Exit ticket</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td>Project 1 <strong>version 1</strong> live on GitHub Pages, passing at least half of your MUST criteria, with at least one automated test passing · README acceptance table · <code>TESTS.md</code> · <code>PROMPTS.md</code> · <code>docs/bake-off-scorecard.md</code> · on Canvas: your bake-off Verdict (this week&#39;s reflection). Details: <a href="./homework.html">homework</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: the app builders, building Project 1 with a chat assistant · 🟡 AI limited: your tests (you choose the cases and expected results; the AI may explain errors), revising <code>SPEC.md</code> · 🔴 AI off: the Verdict, your teach-backs, &quot;What I wrote or decided myself&quot;, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a>, the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td><a href="./bake-off-scorecard.html">Bake-off scorecard</a> · <a href="./../../resources/safe-loop.html">The Safe Loop</a> · <a href="./../../templates/PROJECT_README.html">Project README template</a> · <a href="./../../projects/project-1-useful-tool.html">Project 1 brief</a> · <a href="./../../setup/codespaces.html#preview-a-static-site">Preview a static site</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>A public Project 1 repository with <code>SPEC.md</code> and an <code>index.html</code> that opens at your GitHub Pages address, even if only one criterion passes. Week 7 debugs it</td></tr><tr><td><strong>Time</strong></td><td>Studios 2 × 75 min · outside about 6 h (prep up to 30 min, homework core about 3 h, project time about 2 h, <code>PROMPTS.md</code> and reflection about 30 min); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Judge an app against written acceptance criteria instead of by how it looks.</li><li>Find what an app builder generated behind its preview, read its usage dashboard, and say how you&#39;d export your work to avoid lock-in.</li><li>Keep a web app&#39;s rules in a module of pure functions, apart from the code that touches the page and storage.</li><li>Write an automated test before the code it checks, and watch it go from red to green.</li><li>Test each step in a Codespace preview before you commit it, and read the Console when the page goes blank.</li><li>Publish a first version with an acceptance table that says honestly what passes.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Finish the week 5 homework: a revised <code>SPEC.md</code>, <code>TESTS.md</code> with a logic plan, and your first failing test.</li><li>☐ Check your sign-in for the builder you were given. Under 18, or in the EEA, UK or Switzerland? Your instructor will tell you which builder to use.</li><li>☐ Skim the <a href="./bake-off-scorecard.html">bake-off scorecard</a>.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap · concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-06.html" target="_blank" rel="noreferrer">slides</a>) · live demo: a builder&#39;s usage page and files view · lab: the bake-off jigsaw · checkpoint share: the class results board</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>Show and tell · mini-demo: red, then green · lab: start Project 1 in a Codespace · project work time · exit ticket (🔴 AI off)</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Core and stretch, with the deliverables checklist (must read)</td></tr><tr><td><a href="./bake-off-scorecard.html">Bake-off scorecard</a></td><td>The table you fill in while testing a builder, and the Verdict questions</td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-06.html" target="_blank" rel="noreferrer">Slides</a></td><td>Studio A&#39;s concept talk</td></tr><tr><td><a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">Rescue starter</a></td><td>Sam&#39;s app from the <a href="./../05-spec-first/example-spec.html">example spec</a>, in the layout you&#39;ll use: <code>app.js</code>, <code>lib/</code>, <code>tests/</code></td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>Working on your own? Read this section, then do the <a href="./lab.html">lab</a>; the <a href="./../../resources/self-paced.html">self-paced path</a> replaces the pair activities.</p><p><strong>Judge by criteria, not vibes.</strong> The first builder that looks polished will feel like the winner. Your criteria are the scoreboard: test them in order, write what happened, count the MUSTs that pass. A beautiful app that fails AC3 fails AC3. When a criterion fails in two builders, suspect the spec first.</p><p><strong>What&#39;s under the hood.</strong> Last week you heard that <a href="./../../resources/glossary.html#app-builder">app builders</a> generate a whole project. Now you look: a <code>package.json</code> listing libraries, files ending <code>.tsx</code> (usually React), a <code>&quot;build&quot;</code> script (a <a href="./../../resources/glossary.html#build-step">build step</a>), maybe a database or login you didn&#39;t ask for. Could you debug it with the AI switched off?</p><p><strong>Lock-in and credits.</strong> If a builder shuts down or changes its free tier, an app that lives only there goes with it. Some builders the course used to recommend have closed (<a href="./../../TOOLS.html#do-not-use-in-this-course">Tool Handout</a>), so anything you keep lives in GitHub. Builders run on credits: read the usage dashboard before and after. Students in CMU&#39;s AI coding course ran out mid-assignment (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">CMU 15-113</a>).</p><p><strong>The version you keep.</strong> Your Project 1 stays plain: <code>index.html</code> (structure), <code>style.css</code> (looks), <code>app.js</code> (behavior) and <code>lib/</code> (the rules), with no framework and no build step. You can read every line, next week you debug it with the AI off, and GitHub Pages hosts it free.</p><p><strong>Rules in their own module.</strong> <code>app.js</code> is the only file that touches the page (the <a href="./../../resources/glossary.html#dom">DOM</a>, through <code>document</code>) and storage. The rules from your logic plan live in <code>lib/</code> as <a href="./../../resources/glossary.html#pure-function">pure functions</a> that a <a href="./../../resources/glossary.html#module">module</a> shares with <code>export</code>; <code>app.js</code> loads them with <code>import</code>, and so does your test, which Node runs without a browser. In Python terms: functions you can import into a test, not logic tangled up with <code>input()</code> and <code>print()</code>. Anything that needs today&#39;s date takes it as an argument.</p><p><strong>Check first, now with a test.</strong> From this week, where the logic allows it, the check you write before asking for code is an <strong>automated test</strong>: run it, see it fail (red), ask for the step, see it pass (green). That&#39;s <a href="./../../resources/glossary.html#redgreen-testing">red/green testing</a>. The order matters: in a 2026 study, tests written after buggy code caught 14% of the faults, against 25% for tests written independently (<a href="https://arxiv.org/abs/2607.05139" target="_blank" rel="noreferrer">Konstantinou et al.</a>). Never let the AI change a test to make it pass. Where there&#39;s no rule to test (a layout, a button&#39;s label), the check is a manual test you write down first (<a href="./../../resources/safe-loop.html#check-first">check first</a>).</p><p><strong>Preview before you commit.</strong> In a <strong><a href="./../../resources/glossary.html#codespace">Codespace</a></strong>, a small web server shows each change before anything is saved to GitHub. That&#39;s the Safe Loop&#39;s order: check first, one step, test (<code>npm test</code> and the preview), read and write a <strong>teach-back</strong> in <code>PROMPTS.md</code>, then commit. A blank page is information: open the <strong>Console</strong> and read the red line first.</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><p>The week 6 exit ticket is 🔴 AI off and graded on completion, not correctness. It opens with a look-back question about your week 4 work, answered from memory. Its central question: <em>given a spec and what an app actually does, which acceptance criteria fail, and why?</em> To check yourself first:</p><ul><li>Name a criterion that failed in the bake-off, and say whether the builder or your spec was at fault.</li><li>Name one thing a builder generated that you didn&#39;t ask for, and why it matters.</li><li>Explain why the functions in <code>lib/</code> must not use <code>document</code> or <code>localStorage</code>.</li><li>Show a test you watched fail before it passed, and say what the red proved.</li></ul><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>Core (about 5 hours with project time): Project 1 <strong>version 1</strong> live, passing at least half of your MUST criteria, with at least one automated test passing; a README with an acceptance table; <code>TESTS.md</code>; <code>PROMPTS.md</code>; your scorecard. On Canvas: the bake-off Verdict, this week&#39;s reflection. Details: <a href="./homework.html">homework</a>. The <strong>final version</strong> is due before week 9 Studio A, with at least three automated tests of its pure logic, graded with the <a href="./../../assessment/rubrics.html#project-1">Project 1 rubric</a> and oral walkthrough 1 in week 8.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If this fails</th><th>Do this</th></tr></thead><tbody><tr><td>Google AI Studio (down, age-restricted, or out of quota)</td><td>Use Bolt as builder A, and Lovable or v0 as builder B (<a href="./../../TOOLS.html">Tool Handout</a>)</td></tr><tr><td>Every builder is unavailable</td><td>Run the bake-off with two chat assistants instead (for example Gemini Canvas and ChatGPT), with the same prompt and scorecard</td></tr><tr><td>Your chat assistant</td><td>Switch to a fallback in the <a href="./../../TOOLS.html">Tool Handout</a> and paste your <code>SPEC.md</code> into a fresh chat</td></tr><tr><td>Codespaces won&#39;t start, or you&#39;re out of hours</td><td>Edit in github.dev (press <code>.</code> on your repository page) and test on GitHub Pages after each commit. It has no terminal, so <code>npm test</code> waits (<a href="./../../resources/troubleshooting.html#my-codespace-wont-start-or-im-out-of-hours">troubleshooting</a>)</td></tr><tr><td>GitHub Pages is slow to update</td><td>Wait up to 10 minutes and check the <strong>Actions</strong> tab. Keep testing in your Codespace preview meanwhile</td></tr><tr><td>Out of credits anywhere</td><td><a href="./../../resources/troubleshooting.html#i-ran-out-of-free-credits">I ran out of free credits</a></td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Node&#39;s built-in test runner, the one <code>npm test</code> uses: <a href="https://nodejs.org/api/test.html" target="_blank" rel="noreferrer">https://nodejs.org/api/test.html</a></li><li>MDN&#39;s guide to JavaScript modules (<code>export</code>, <code>import</code>, <code>&lt;script type=&quot;module&quot;&gt;</code>): <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Modules" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Modules</a></li><li>The course <a href="./../../resources/reading-list.html">reading list</a> and <a href="./../../resources/prompt-patterns.html">prompt patterns</a></li></ul>',31)])])}const f=t(s,[["render",i]]);export{p as __pageData,f as default};
